import JSZip from 'jszip'

/**
 * Put named files in one ZIP, without compressing their contents.
 * Input: [{ name: 'b1.stl', content: 'solid b0\n...' }, { name: 'data1.txt', content: '0\t0\t0\n' }].
 * Output: Promise<ArrayBuffer> containing both files under their original names.
 */
// shortcut: complete ZIPs stay in memory; use a worker/streaming output if production files freeze the UI or exceed memory.
export async function zipFiles(files) {
  const zip = new JSZip()
  for (const file of files) zip.file(file.name, file.content)
  return zip.generateAsync({ type: 'arraybuffer', compression: 'STORE' })
}
